    assert criteria["minimumDistinctWorksPerRecord"] == 3
    for verse_id in ("9:91", "9:92"):
        verse = DATA["verses"][verse_id]
        works = {item["work"] for item in verse["sourceMix"] if item["role"] in ("classical", "modern", "academic")}
